Here is the root cause:
During switchdev mode failure, the rollback path in `esw_offloads_enable` calls `mlx5_esw_offloads_rep_unload` without first setting the `MLX5_PRIV_FLAGS_SWITCH_LEGACY` flag. This causes the uplink netdev to be unregistered, but the system still expects it to be registered, leading to a kernel bug.

Here is the patch:

 int esw_offloads_enable(struct mlx5_eswitch *esw)
 {
 	u8 mapping_id[MLX5_SW_IMAGE_GUID_MAX_BYTES];
 	struct mapping_ctx *reg_c0_obj_pool;
 	struct mlx5_vport *vport;
 	unsigned long i;
 	u8 id_len;
 	int err;

 	mutex_init(&esw->offloads.termtbl_mutex);
 	mlx5_esw_adjacent_vhcas_setup(esw);

 	err = mlx5_rdma_enable_roce(esw->dev);
 	if (err)
 		goto err_roce;

 	err = mlx5_esw_host_number_init(esw);
 	if (err)
 		goto err_metadata;

 	err = esw_offloads_metadata_init(esw);
 	if (err)
 		goto err_metadata;

 	err = esw_set_passing_vport_metadata(esw, true);
 	if (err)
 		goto err_vport_metadata;

 	mlx5_query_nic_sw_system_image_guid(esw->dev, mapping_id, &id_len);

 	reg_c0_obj_pool = mapping_create_for_id(mapping_id, id_len,
 						MAPPING_TYPE_CHAIN,
 						sizeof(struct mlx5_mapped_obj),
 						ESW_REG_C0_USER_DATA_METADATA_MASK,
 						true);

 	if (IS_ERR(reg_c0_obj_pool)) {
 		err = PTR_ERR(reg_c0_obj_pool);
 		goto err_pool;
 	}
 	esw->offloads.reg_c0_obj_pool = reg_c0_obj_pool;

 	err = esw_offloads_steering_init(esw);
 	if (err)
 		goto err_steering_init;

 	if (esw->offloads_inactive)
 		mlx5_esw_fdb_inactive(esw);
 	else
 		mlx5_esw_fdb_active(esw);

 	/* Representor will control the vport link state */
 	mlx5_esw_for_each_vf_vport(esw, i, vport, esw->esw_funcs.num_vfs)
 		vport->info.link_state = MLX5_VPORT_ADMIN_STATE_DOWN;
 	if (mlx5_core_ec_sriov_enabled(esw->dev))
 		mlx5_esw_for_each_ec_vf_vport(esw, i, vport, esw->esw_funcs.num_ec_vfs)
 			vport->info.link_state = MLX5_VPORT_ADMIN_STATE_DOWN;

 	/* Uplink vport rep must load first. */
 	err = mlx5_esw_offloads_rep_load(esw, MLX5_VPORT_UPLINK);
 	if (err)
 		goto err_uplink;

 	err = mlx5_eswitch_enable_pf_vf_vports(esw, MLX5_VPORT_UC_ADDR_CHANGE);
 	if (err)
 		goto err_vports;

 	return 0;

 err_vports:
+	/* rollback to legacy, indicates don't unregister the uplink netdev */
+	esw->dev->priv.flags |= MLX5_PRIV_FLAGS_SWITCH_LEGACY;
 	mlx5_esw_offloads_rep_unload(esw, MLX5_VPORT_UPLINK);
 err_uplink:
 	esw_offloads_steering_cleanup(esw);
 err_steering_init:
 	mapping_destroy(reg_c0_obj_pool);
 err_pool:
 	esw_set_passing_vport_metadata(esw, false);
 err_vport_metadata:
 	esw_offloads_metadata_uninit(esw);
 err_metadata:
 	mlx5_rdma_disable_roce(esw->dev);
 err_roce:
 	mlx5_esw_adjacent_vhcas_cleanup(esw);
 	mutex_destroy(&esw->offloads.termtbl_mutex);
 	return err;
 }



